// Report-type result (D9): what it covers (period + filters as chips), the KPI summary, the chart whose title states
// the finding, then the detailed table with a totals row (cards on phones) — all computed by the server. Also builds
// the export (PDF with letterhead, filters, generated by/at, page numbers, chart + table; Excel; CSV).
import { useState, type RefObject } from 'react'
import type { ReportColType, ReportTypeResult } from '@/api/types/viz'
import { Badge, Button, Callout, Card, DataTable, EmptyState, type Column } from '@/ui'
import { SERIES } from '@/ui/charts'
import { Rows3 } from '@/ui/icons'
import type { ExportColType, ExportTable } from '@/reports/export'
import { fmtDate, fmtDateTime } from '@/domain/calendar'
import { cn } from '@/lib/utils'
import { Kpi } from '@/modules/insights/kit'
import { VizCard } from '@/modules/insights/viz/VizCard'
import { seriesColour } from '@/modules/insights/viz/Cartesian'
import { fmtViz } from '@/modules/insights/viz/format'

type Row = Record<string, string | number | boolean | null>
const NUMERIC: ReportColType[] = ['money', 'number', 'percent', 'hours', 'days', 'ratio']

export function cellText(v: unknown, t: ReportColType): string {
  if (v === null || v === undefined || v === '') return '—'
  if (typeof v === 'boolean') return v ? 'Yes' : 'No'
  if (t === 'date') return fmtDate(String(v).slice(0, 10))
  if (NUMERIC.includes(t)) return fmtViz(v, t === 'number' ? 'number' : t)
  return String(v)
}

function exportType(t: ReportColType): ExportColType {
  return t === 'money' ? 'money' : t === 'percent' ? 'percent' : t === 'hours' ? 'hours' : t === 'date' ? 'date' : t === 'number' || t === 'days' || t === 'ratio' ? 'number' : 'string'
}

export function toTypedExport(r: ReportTypeResult, name: string, chartEl: HTMLElement | null): ExportTable {
  const svg = chartEl?.querySelector('svg.recharts-surface') as SVGSVGElement | null
  return {
    title: name,
    subtitle: [r.period?.label ?? null, r.saved ? r.title : null].filter(Boolean).join(' · ') || r.title,
    category: `${r.category_label} report`,
    columns: r.columns.map((c) => ({ key: c.key, label: c.label, type: exportType(c.type) })),
    rows: r.rows,
    totals: Object.keys(r.totals).length ? r.totals : undefined,
    kpis: r.kpis.map((k) => ({ label: k.label, value: fmtViz(k.value, k.format) })),
    filters: r.filters_applied.map((f) => ({ label: f.label, value: f.value })),
    notes: r.warnings,
    // V9-FIX (item 4): doughnut charts go into the PDF like the other kinds; their legend (category, value, share) is
    // HTML on screen, so it is rebuilt here in the same colours
    chartSvg: r.chart ? svg : null,
    chartTitle: r.chart ? `${r.chart.title} — ${r.chart.subtitle ?? ''}`.replace(/ — $/, '') : undefined,
    legend: r.chart ? chartLegend(r.chart) : undefined,
    asOf: r.period && r.period.to < r.generated_at.slice(0, 10) ? r.period.to : undefined,
  }
}

function chartLegend(c: NonNullable<ReportTypeResult['chart']>): ExportTable['legend'] {
  if (c.kind === 'donut') {
    const vals = c.categories.map((_, i) => Number(c.series[0]?.values[i] ?? 0))
    const total = vals.reduce((a, b) => a + b, 0) || 1
    return c.categories.map((cat, i) => ({ label: `${cat}: ${fmtViz(vals[i], c.format)} (${Math.round((vals[i] / total) * 100)}%)`, color: SERIES[i % SERIES.length] }))
  }
  return c.series.length > 1 ? c.series.map((s, i) => ({ label: s.label, color: seriesColour(i, c.series.length) })) : undefined
}

function ResultTable({ r }: { r: ReportTypeResult }) {
  const [limit, setLimit] = useState(200)
  const cols: Column<Row>[] = r.columns.map((c, i) => ({
    key: c.key,
    header: c.label,
    align: c.align === 'right' ? 'right' : undefined,
    hideBelow: undefined,
    cell: (row: Row) => <span className={cn(c.align === 'right' && 'tnum whitespace-nowrap', i === 0 && 'font-medium text-ink')}>{cellText(row[c.key], c.type)}</span>,
    sortValue: (row: Row) => (typeof row[c.key] === 'number' || typeof row[c.key] === 'string' ? (row[c.key] as string | number) : null),
  }))
  const hasTotals = Object.keys(r.totals).length > 0
  const rows: Row[] = r.rows.slice(0, limit).map((x, i) => ({ ...x, __i: i }))
  const first = r.columns[0]
  const rest = r.columns.slice(1)
  return (
    <>
      <DataTable
        rows={rows}
        rowKey={(x) => String(x.__i)}
        columns={cols}
        dense
        pageSize={limit}
        empty={<EmptyState compact icon={<Rows3 />} title="No rows" body="Nothing matches these filters. Widen the period or clear a filter." />}
        footer={
          hasTotals ? (
            <tr>
              {r.columns.map((c, i) => (
                <td key={c.key} className={cn('px-3 py-2.5 text-[13px] md:px-4', c.align === 'right' && 'tnum whitespace-nowrap text-right')}>
                  {i === 0 ? 'Total' : r.totals[c.key] !== undefined ? cellText(r.totals[c.key], c.type) : ''}
                </td>
              ))}
            </tr>
          ) : undefined
        }
        mobileCard={(row) => (
          <div className="space-y-2">
            <div className="min-w-0 truncate text-[14px] font-medium">{first ? cellText(row[first.key], first.type) : ''}</div>
            <dl className="grid grid-cols-2 gap-x-3 gap-y-1.5 text-[12.5px]">
              {rest.map((c) => (
                <div key={c.key} className="min-w-0">
                  <dt className="text-[11px] text-ink-3">{c.label}</dt>
                  <dd className={cn('min-w-0 truncate', NUMERIC.includes(c.type) && 'tnum')}>{cellText(row[c.key], c.type)}</dd>
                </div>
              ))}
            </dl>
          </div>
        )}
      />
      {hasTotals && (
        <div className="mt-2 rounded-lg border border-line bg-surface-2/60 p-3 md:hidden">
          <div className="mb-1.5 text-[12px] font-semibold text-ink">Totals</div>
          <dl className="grid grid-cols-2 gap-x-3 gap-y-1.5 text-[12.5px]">
            {r.columns
              .filter((c) => r.totals[c.key] !== undefined)
              .map((c) => (
                <div key={c.key} className="min-w-0">
                  <dt className="text-[11px] text-ink-3">{c.label}</dt>
                  <dd className="tnum truncate font-semibold">{cellText(r.totals[c.key], c.type)}</dd>
                </div>
              ))}
          </dl>
        </div>
      )}
      {r.rows.length > limit && (
        <div className="mt-3 flex justify-center">
          <Button size="sm" onClick={() => setLimit((l) => l + 500)}>
            Show more rows ({(r.rows.length - limit).toLocaleString('en-IN')} left)
          </Button>
        </div>
      )}
    </>
  )
}

export function TypeResult({ r, fetching, chartRef }: { r: ReportTypeResult; fetching?: boolean; chartRef: RefObject<HTMLDivElement> }) {
  return (
    <div className={cn('space-y-4 transition-opacity', fetching && 'opacity-60')}>
      <div className="flex flex-wrap items-center gap-1.5" aria-label="Filters used">
        {r.filters_applied.map((f) => (
          <span key={f.key} className="inline-flex max-w-full items-center gap-1 rounded-md border border-line bg-surface px-2 py-1 text-[12px]">
            <span className="text-ink-3">{f.label}</span>
            <span className="min-w-0 truncate font-medium text-ink">{f.value}</span>
          </span>
        ))}
        <span className="text-[12px] text-ink-3">
          {r.row_count.toLocaleString('en-IN')} {r.grouped ? (r.row_count === 1 ? 'group' : 'groups') : r.row_count === 1 ? 'row' : 'rows'} · generated {fmtDateTime(r.generated_at)}
          {r.generated_by ? ` by ${r.generated_by}` : ''}
        </span>
      </div>
      {r.warnings.length > 0 && (
        <Callout tone="warning" title="Heads up">
          {r.warnings.join(' ')}
        </Callout>
      )}
      <div className={cn('grid grid-cols-2 gap-2.5 md:gap-3', r.kpis.length >= 4 ? 'lg:grid-cols-4' : 'lg:grid-cols-3')}>
        {r.kpis.map((k) => (
          <Kpi key={k.key} label={k.label} hint={k.hint} tone={k.tone} value={fmtViz(k.value, k.format)} />
        ))}
      </div>
      {r.chart ? <VizCard viz={r.chart} fetching={fetching} chartRef={chartRef} /> : <p className="text-[13px] font-medium text-ink">{r.finding}</p>}
      <Card pad={false} className="overflow-hidden">
        <div className="flex items-center justify-between gap-2 border-b border-line px-4 py-2.5 md:px-5">
          <h2 className="text-[14px] font-semibold">Detail</h2>
          <Badge size="sm" tone="neutral">
            {r.grouped ? `Grouped · ${r.columns[0]?.label}` : `${r.columns.length} columns`}
          </Badge>
        </div>
        <div className="p-0">
          <ResultTable r={r} />
        </div>
      </Card>
    </div>
  )
}
